\", _AIRBYTE_DATA: \"Width(mm)\"::string AS \"Width(mm)\", _AIRBYTE_DATA: \"weight\"::string AS weight, _AIRBYTE_DATA: \"Shipping Courier Status\"::string as \"Shipping Courier Status\", _AIRBYTE_DATA: \"Order_Type\"::string as \"Order_Type\", _AIRBYTE_DATA: \"STORE-CODE\"::string as \"STORE-CODE\", _AIRBYTE_DATA: \"SaleInvoicePrefix\"::string as \"SaleInvoicePrefix\", _AIRBYTE_DATA: \"Order Amount\"::string as \"Order Amount\" FROM snitch_db.maplemonk._airbyte_raw_Snitch_uc_New_get_sale_orders QUALIFY ROW_NUMBER() OVER ( PARTITION BY \"Sale Order Code\"::string, \"Display Order Code\"::string, \"Sale Order Item Code\"::string ORDER BY TRY_CAST(Updated::string AS TIMESTAMP) DESC ) = 1 ), ranked_data AS ( SELECT \"Channel Name\" AS MARKETPLACE, CASE WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%CRED%\' THEN \'CRED\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%M-NOW%\' THEN \'M-NOW\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%SLIKK%\' THEN \'SLIKK\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%FLIPKART%\' and UPPER(TRIM(\"Channel Name\")) LIKE \'%CUSTOM%\' THEN \'FLIPKART_SOR\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%FLIPKART%\' THEN \'FLIPKART\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%SJIT%\' THEN \'MYNTRA_SJIT\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%MYNTRA%\' THEN \'MYNTRA\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%AJIO%\' THEN \'AJIO\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%STORE%\' THEN \'STORE\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%AMAZON%\' THEN \'AMAZON\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%DONOSHOP%\' THEN \'POPCLUB\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%NYKAA_FASHION%\' THEN \'NYKAA_FASHION\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%NYKAA_COM%\' THEN \'NYKAA.COM\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%NYKAA%\' THEN \'NYKAA.COM\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%INSTA%\' THEN \'INSTAMART\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%NOON%\' THEN \'NOON\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%COCOB%\' THEN \'CO