scountcode,\'\') as DISCOUNT_CODE, \"Shipping provider\" AS COURIER, \"Shipping Tracking Status\" AS SHIPPING_STATUS, NULLIF(\"Shipping Package Creation Date\", \'\')::DATE AS CREATED_TIMESTAMP, NULLIF(\"Packing Time\", \'\')::DATE AS PACKED_TIMESTAMP, NULLIF(\"Dispatch Date\", \'\')::DATE AS DISPATCH_DATE, NULLIF(\"Dispatch Date\", \'\')::TIMESTAMP AS DISPATCHED_TIMESTAMP, NULLIF(\"Delivery Time\", \'\')::DATE AS DELIVERED_DATE, NULLIF(\"Delivery Time\", \'\')::TIMESTAMP AS DELIVERED_TIMESTAMP, category, coalesce(nullif(\"Cost Price\",\'\'),0) AS COST, \"Invoice Code\" as INVOICE_CODE, NULLIF(\"Invoice Created\", \'\')::TIMESTAMP AS INVOICE_DATE, \"Tracking Number\" AS AWB, \"Shipping Courier\" AS SHIPPING_COURIER, ROW_NUMBER() OVER (PARTITION BY CONCAT(\"Sale Order Item Code\",\"Display Order Code\",\"Sale Order Code\") ORDER BY NULLIF(UPDATED, \'\') DESC) AS row_num, \"On Hold\" as ON_HOLD, \"Shipping Package Type\" AS SHIPPING_PACKAGE_TYPE, \"Reverse Pickup Code\" as REVERSE_PICKUP_CODE, NULLIF(\"Reverse Pickup Created Date\", \'\')::TIMESTAMP AS REVERSE_PICKUP_CREATED, \"Notification Email\" as NOTIFICATION_EMAIL, \"Notification Mobile\" as NOTIFICATION_MOBILE, \"Require Customization\" as CUSTOMIZATION, COD, \"Shipping Address Id\" as SHIPPING_ID, \"Cancellation Reason\" as CANCELLATION_REASON, \"Shipping Arranged By\" as SHIPPING_ARRANGED_BY, \"Length(mm)\" as PACKAGE_LENGTH, \"Width(mm)\" as PACKAGE_WIDTH, \"Height(mm)\" as PACKAGE_HEIGHT, NULLIF(\"Return Date\", \'\')::TIMESTAMP AS RETURN_DATE, \"Return Reason\" as RETURN_REASON, \"Return Remarks\" as RETURN_REMARKS, \"Item Code\" as ITEM_CODE, weight, \"SKU Name\" as SKU_NAME, \"Shipping Courier Status\" as SHIPPING_COURIER_STATUS, \"Shipping Tracking Status\" as SHIPPING_TRACKING_STATUS, NULLIF(\"Packing Time\", \'\')::TIMESTAMP AS PACKED_TIME, \"Packing User\" as PACKING_USER, CASE WHEN SHIPPING_COURIER_STATUS in (\'COURIER_RETURN-CREATED\',\'COURIER_RETURN-RETURN_CREATED\',\'COURIER_RETURN-CONFIRMED\') 