ESTAMP ,try_Cast(RETURN_DATE as date) AS RETURN_DATE ,DAYS_TO_DISPATCH ,AWB ,RETURN_FLAG ,RETURN_QUANTITY ,CANCELLED_QUANTITY ,NEW_CUSTOMER_FLAG ,ACQUISITION_PRODUCT ,DAYS_IN_SHIPMENT ,DISPATCH_TO_DELIVERY_DAYS ,INVOICE_DATE ,COST ,CATEGORY ,PRODUCT_NAME_SHOPIFY ,PLA_SPENDS ,BANNER_SPENDS ,SALES_TARGET ,SPENDS_TARGET from snitch_db.maplemonk.unicommerce_fact_items_intermediate_old where order_date::date <= \'2024-12-15\' ) UNION ALL ( select MARKETPLACE , CASE WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%CRED%\' THEN \'CRED\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%FLIPKART%\' THEN \'FLIPKART\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%MYNTRA%\' and upper(trim(marketplace)) not like \'%SJIT%\' THEN \'MYNTRA\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%AJIO%\' THEN \'AJIO\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%AMAZON%\' THEN \'AMAZON\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%DONOSHOP%\' THEN \'POPCLUB\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%NYKAA_FASHION%\' THEN \'NYKAA_FASHION\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%NYKAA_COM%\' THEN \'NYKAA.COM\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%COCOB%\' THEN \'COCOBLU\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%NOON%\' THEN \'NOON\' ELSE MARKETPLACE END AS MARKETPLACE_MAPPED ,null as SOURCE ,ORDER_ID ,ORDER_NAME ,FULFILLMENT_TAT::timestamp ,UC_CREATED ,SHIPPING_LAST_UPDATE_DATE ,SHIPPING_LAST_UPDATE_TIMESTAMP ,SKU ,SKU_GROUP ,PRODUCT_ID ,null as PRODUCT_NAME ,SALE_ORDER_ITEM_STATUS ,ITEM_DETAILS ,null as CURRENCY ,ADDRESS_LINE_1 ,ADDRESS_LINE_2 ,CITY ,STATE ,COUNTRY ,PINCODE ,ORDER_STATUS ,ORDER_DATE ,ORDER_TIMESTAMP ,null as SHIPPING_PRICE ,1 as SUBORDER_QUANTITY ,1 as SHIPPING_QUANTITY ,DISCOUNT::float ,TRY_CAST(TAX as float) as TAX ,SELLING_PRICE ,SHIPPINGPACKAGECODE ,SHIPPINGPACKAGESTATUS ,WAREHOUSE_NAME ,SALEORDERITEMCODE ,MRP::float ,COURIER ,SHIPPING_COURIER ,SHIPPING_STATUS ,CREATED_TIMESTAMP ,null as PICKING_TIMESTAMP ,null as PICKED_TIMESTAMP ,PACKED_TIMESTAMP ,null as MANIFESTED_TIMESTAMP ,DISPATCHED_TIMESTAMP ,DISPATCH_DATE ,DELIVERED_DATE ,DELIVERED_TIMESTAMP ,RETURN_DATE ,null as DAYS_TO_DISPATCH ,AWB ,null as RETURN_FLAG ,null as RETURN_QUANTITY ,null as CANCELLED_QUANTITY ,null as NEW_CUSTOMER_FLAG ,null as ACQUISITION_PRODUCT ,null as DAYS_IN_SHIPMENT ,null as DISPATCH_TO_DELIVERY_DAYS ,INVOICE_DATE ,COST::float ,CATEGORY ,null as PRODUCT_NAME_SHOPIFY ,null as PLA_SPENDS ,null as BANNER_SPENDS ,null as SALES_TARGET ,null as SPENDS_TARGET from snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 where order_date::date > \'2024-12-15\' and not(lower(order_name) in ( select distinct lower(order_name) from snitch_db.maplemonk.unicommerce_fact_items_intermediate_old where order_date::date <= \'2024-12-15\' )) );",
